import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { SampleBase } from './sample-base';
import { AccumulationChartComponent, AccumulationSeriesCollectionDirective, AccumulationSeriesDirective, Inject, AccumulationLegend, PieSeries, AccumulationTooltip, AccumulationDataLabel, AccumulationAnnotation, AccumulationAnnotationsDirective, AccumulationAnnotationDirective } from '@syncfusion/ej2-react-charts';
import { Browser } from "@syncfusion/ej2/base";
const SAMPLE_CSS = `
  .control-fluid {
    padding: 0px !important;
  }
  .pie-chart {
    align: center;
  }
`;
const chartData = [
    { x: 'Operations', y: 30.0, text: '30.0%' },
    { x: 'Miscellaneous', y: 10.0, text: '10.0%' },
    { x: 'Human Resources', y: 15.0, text: '15.0%' },
    { x: 'Research and Development', y: 20.0, text: '20.0%' },
    { x: 'Marketing', y: 25.0, text: '25.0%' }
];
class PieCornerRadius extends SampleBase {
    onPointRender(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Material';
        if (selectedTheme.indexOf('dark') > -1) {
            if (selectedTheme.indexOf('material') > -1) {
                args.border.color = '#303030';
            }
            else if (selectedTheme.indexOf('bootstrap5') > -1) {
                args.border.color = '#212529';
            }
            else if (selectedTheme.indexOf('bootstrap') > -1) {
                args.border.color = '#1A1A1A';
            }
            else if (selectedTheme.indexOf('fabric') > -1) {
                args.border.color = '#201f1f';
            }
            else if (selectedTheme.indexOf('fluent') > -1) {
                args.border.color = '#252423';
            }
            else if (selectedTheme.indexOf('tailwind') > -1) {
                args.border.color = '#1F2937';
            }
            else {
                args.border.color = '#222222';
            }
        }
        else if (selectedTheme.indexOf('highcontrast') > -1) {
            args.border.color = '#000000';
        }
        else {
            args.border.color = '#FFFFFF';
        }
    }
    load(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Fluent2';
        args.accumulation.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).replace(/-dark/i, "Dark").replace(/light/i, "Light").replace(/contrast/i, 'Contrast').replace(/-highContrast/i, 'HighContrast');
    }
    onChartLoad(args) {
        document.getElementById('pie-chart').setAttribute('title', '');
    }
    render() {
        return (<div className='control-pane'>
                <style>{SAMPLE_CSS}</style>
                <div className='control-section row'>
                    <AccumulationChartComponent id='pie-chart' title='Company Budget Distribution' load={this.load.bind(this)} style={{ textAlign: 'center' }} legendSettings={{ visible: false }} enableSmartLabels={true} enableAnimation={false} center={{ x: '50%', y: '50%' }} enableBorderOnMouseMove={false} width={Browser.isDevice ? '100%' : '75%'} tooltip={{ enable: true, format: '<b>${point.x}</b>: <b>${point.y}%</b>', header: '<b>Budget</b>' }} loaded={this.onChartLoad.bind(this)} pointRender={this.onPointRender}>
                        <Inject services={[AccumulationLegend, PieSeries, AccumulationTooltip, AccumulationDataLabel, AccumulationAnnotation]}/>
                        <AccumulationSeriesCollectionDirective>
                            <AccumulationSeriesDirective dataSource={chartData} name='Company Budget' xName='x' yName='y' type='Pie' innerRadius='50%' dataLabel={{
                visible: true,
                position: 'Outside',
                name: 'x',
                connectorStyle: { width: 0 }
            }} borderRadius={8} border={{ width: 3 }}/>
                        </AccumulationSeriesCollectionDirective>
                        <AccumulationAnnotationsDirective>
                            <AccumulationAnnotationDirective content='<div style="padding: 5px 5px 5px 5px">30%</div>' region='Series' coordinateUnits='Point' x='Operations' y={30.0}/>
                            <AccumulationAnnotationDirective content='<div style="padding: 5px 5px 5px 5px">10%</div>' region='Series' coordinateUnits='Point' x='Miscellaneous' y={10.0}/>
                            <AccumulationAnnotationDirective content='<div style="padding: 5px 5px 5px 5px">15%</div>' region='Series' coordinateUnits='Point' x='Human Resources' y={15.0}/>
                            <AccumulationAnnotationDirective content='<div style="padding: 5px 5px 5px 5px">20%</div>' region='Series' coordinateUnits='Point' x='Research and Development' y={20.0}/>
                            <AccumulationAnnotationDirective content='<div style="padding: 5px 5px 5px 5px">25%</div>' region='Series' coordinateUnits='Point' x='Marketing' y={25.0}/>
                        </AccumulationAnnotationsDirective>
                    </AccumulationChartComponent>
                </div>
            </div>);
    }
}
export default PieCornerRadius;

const root = createRoot(document.getElementById('sample'));
root.render(<PieCornerRadius />);

